alter table `crm_reminders` ADD INDEX IF NOT EXISTS `crm_reminders_status_index`(`status`);
CREATE TABLE IF NOT EXISTS `crm_activities` (`id` bigint unsigned not null auto_increment primary key, `lead_id` bigint unsigned not null, `user_id` bigint unsigned null, `type` varchar(30) not null, `title` varchar(255) not null, `body` text null, `meta` json null, `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci' engine = InnoDB;
alter table `crm_activities` add constraint `crm_activities_lead_id_foreign` FOREIGN KEY IF NOT EXISTS (`lead_id`) references `crm_leads` (`id`) on delete cascade;
alter table `crm_activities` ADD INDEX IF NOT EXISTS `crm_activities_lead_id_created_at_index`(`lead_id`, `created_at`);
alter table `crm_activities` ADD INDEX IF NOT EXISTS `crm_activities_type_index`(`type`);
CREATE TABLE IF NOT EXISTS `crm_templates` (`id` bigint unsigned not null auto_increment primary key, `name` varchar(80) not null, `channel` varchar(10) not null, `body` text not null, `sort` smallint unsigned not null default '0', `is_active` tinyint(1) not null default '1', `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci' engine = InnoDB;
alter table `crm_templates` ADD INDEX IF NOT EXISTS `crm_templates_channel_index`(`channel`);
