-- Library sidebar (menus, guard library): the final layout of all the menu migrations.
-- Rows are found by url, never by id. Old items are hidden (status 0), never deleted.
--   Dashboard | Learners | Attendance | Student Chat | Reports (one link) | Setup | Staff | Settings | Account

-- check: all six must be numbers (NULL = stop and ask)
SELECT (SELECT `gid` FROM (SELECT `parent_id` AS `gid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `url` = 'seats' AND `parent_id` IS NOT NULL ORDER BY `menus`.`id` LIMIT 1) g1) AS learners, (SELECT `gid` FROM (SELECT `parent_id` AS `gid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `url` = 'get.learner.attendance' AND `parent_id` IS NOT NULL ORDER BY `menus`.`id` LIMIT 1) g2) AS attendance, (SELECT `gid` FROM (SELECT `id` AS `gid` FROM `menus` WHERE `parent_id` IS NULL AND `deleted_at` IS NULL AND `has_permissions` = 'Manage Report' ORDER BY `menus`.`id` LIMIT 1) gr1) AS reports, (SELECT `gid` FROM (SELECT `parent_id` AS `gid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `url` = 'branch.list' AND `parent_id` IS NOT NULL ORDER BY `menus`.`id` LIMIT 1) g3) AS setup, (SELECT `gid` FROM (SELECT `parent_id` AS `gid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `url` = 'toggle.feature' AND `parent_id` IS NOT NULL ORDER BY `menus`.`id` LIMIT 1) g4) AS settings, (SELECT `gid` FROM (SELECT `parent_id` AS `gid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `url` = 'profile' AND `parent_id` IS NOT NULL ORDER BY `menus`.`id` LIMIT 1) g5) AS account;

-- new top-level groups (only when missing): Staff, Student Chat
INSERT INTO `menus` (`name`, `url`, `icon`, `parent_id`, `order`, `guard`, `status`, `has_permissions`, `created_at`, `updated_at`) SELECT 'Staff', 'library-users.index', 'fa fa-users', NULL, 7, 'library', 1, 'Add User', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `menus` x WHERE x.`guard` = 'library' AND x.`deleted_at` IS NULL AND x.`url` = 'library-users.roles' AND x.`parent_id` IS NOT NULL)
  AND NOT EXISTS (SELECT 1 FROM `menus` x WHERE x.`guard` = 'library' AND x.`deleted_at` IS NULL AND x.`parent_id` IS NULL AND x.`name` = 'Staff');
INSERT INTO `menus` (`name`, `url`, `icon`, `parent_id`, `order`, `guard`, `status`, `has_permissions`, `created_at`, `updated_at`) SELECT 'Student Chat', 'chat.index', 'fa fa-comments', NULL, 4, 'library', 1, NULL, NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `menus` x WHERE x.`guard` = 'library' AND x.`url` = 'chat.index' AND x.`deleted_at` IS NULL);

-- new links (only when missing)
INSERT INTO `menus` (`name`, `url`, `icon`, `parent_id`, `order`, `guard`, `status`, `has_permissions`, `created_at`, `updated_at`) SELECT 'Role', 'library-users.roles', NULL, (SELECT `gid` FROM (SELECT `id` AS `gid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `parent_id` IS NULL AND `name` IN ('Staff', 'Staff Management') ORDER BY `menus`.`id` LIMIT 1) g6), 2, 'library', 1, 'Add User', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `menus` x WHERE x.`guard` = 'library' AND x.`url` = 'library-users.roles' AND x.`deleted_at` IS NULL);
INSERT INTO `menus` (`name`, `url`, `icon`, `parent_id`, `order`, `guard`, `status`, `has_permissions`, `created_at`, `updated_at`) SELECT 'Permission', 'library-users.permission-list', NULL, (SELECT `gid` FROM (SELECT `parent_id` AS `gid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `url` = 'library-users.roles' AND `parent_id` IS NOT NULL ORDER BY `menus`.`id` LIMIT 1) g7), 3, 'library', 1, 'Add User', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `menus` x WHERE x.`guard` = 'library' AND x.`url` = 'library-users.permission-list' AND x.`deleted_at` IS NULL);
INSERT INTO `menus` (`name`, `url`, `icon`, `parent_id`, `order`, `guard`, `status`, `has_permissions`, `created_at`, `updated_at`) SELECT 'Library Settings', 'library.settings', NULL, (SELECT `gid` FROM (SELECT `parent_id` AS `gid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `url` = 'toggle.feature' AND `parent_id` IS NOT NULL ORDER BY `menus`.`id` LIMIT 1) g8), 1, 'library', 1, 'Library Genral Settings', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `menus` x WHERE x.`guard` = 'library' AND x.`url` = 'library.settings' AND x.`deleted_at` IS NULL AND x.`parent_id` IN ((SELECT `gid` FROM (SELECT `parent_id` AS `gid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `url` = 'toggle.feature' AND `parent_id` IS NOT NULL ORDER BY `menus`.`id` LIMIT 1) g9), (SELECT `gid` FROM (SELECT `parent_id` AS `gid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `url` = 'profile' AND `parent_id` IS NOT NULL ORDER BY `menus`.`id` LIMIT 1) g10)));
INSERT INTO `menus` (`name`, `url`, `icon`, `parent_id`, `order`, `guard`, `status`, `has_permissions`, `created_at`, `updated_at`) SELECT 'Feedback', 'library.feedback', NULL, (SELECT `gid` FROM (SELECT `parent_id` AS `gid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `url` = 'profile' AND `parent_id` IS NOT NULL ORDER BY `menus`.`id` LIMIT 1) g11), 5, 'library', 1, NULL, NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `menus` x WHERE x.`guard` = 'library' AND x.`url` = 'library.feedback' AND x.`deleted_at` IS NULL);
INSERT INTO `menus` (`name`, `url`, `icon`, `parent_id`, `order`, `guard`, `status`, `has_permissions`, `created_at`, `updated_at`) SELECT 'Student Quiz', 'quiz.index', NULL, (SELECT `gid` FROM (SELECT `parent_id` AS `gid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `url` = 'toggle.feature' AND `parent_id` IS NOT NULL ORDER BY `menus`.`id` LIMIT 1) g12), 5, 'library', 1, NULL, NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `menus` x WHERE x.`guard` = 'library' AND x.`url` = 'quiz.index' AND x.`deleted_at` IS NULL);
INSERT INTO `menus` (`name`, `url`, `icon`, `parent_id`, `order`, `guard`, `status`, `has_permissions`, `created_at`, `updated_at`) SELECT 'Global Discount', 'global-discount.index', NULL, (SELECT `gid` FROM (SELECT `parent_id` AS `gid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `url` = 'branch.list' AND `parent_id` IS NOT NULL ORDER BY `menus`.`id` LIMIT 1) g13), 7, 'library', 1, NULL, NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `menus` x WHERE x.`guard` = 'library' AND x.`url` = 'global-discount.index' AND x.`deleted_at` IS NULL);
-- report pages of the reports redesign (hidden: Reports is one link to the hub)
INSERT INTO `menus` (`name`, `url`, `icon`, `parent_id`, `order`, `guard`, `status`, `has_permissions`, `created_at`, `updated_at`) SELECT v.`name`, v.`url`, NULL, (SELECT `gid` FROM (SELECT `id` AS `gid` FROM `menus` WHERE `parent_id` IS NULL AND `deleted_at` IS NULL AND `has_permissions` = 'Manage Report' ORDER BY `menus`.`id` LIMIT 1) gr1), v.`ord`, 'library', 0, 'Manage Report', NOW(), NOW()
FROM (SELECT 'Overview' AS `name`, 'reports.hub' AS `url`, 1 AS `ord` UNION ALL SELECT 'Growth & retention', 'reports.growth', 8 UNION ALL SELECT 'Seat occupancy', 'reports.occupancy', 9) v
WHERE (SELECT `gid` FROM (SELECT `id` AS `gid` FROM `menus` WHERE `parent_id` IS NULL AND `deleted_at` IS NULL AND `has_permissions` = 'Manage Report' ORDER BY `menus`.`id` LIMIT 1) gr1) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `menus` x WHERE x.`parent_id` = (SELECT `gid` FROM (SELECT `id` AS `gid` FROM `menus` WHERE `parent_id` IS NULL AND `deleted_at` IS NULL AND `has_permissions` = 'Manage Report' ORDER BY `menus`.`id` LIMIT 1) gr1) AND x.`url` = v.`url`);

-- top-level menus: name, order
UPDATE `menus` SET `order` = 1, `updated_at` = NOW() WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `parent_id` IS NULL AND `url` = 'library.home';
UPDATE `menus` SET `name` = 'Learners', `order` = 2, `updated_at` = NOW() WHERE `id` = (SELECT `gid` FROM (SELECT `parent_id` AS `gid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `url` = 'seats' AND `parent_id` IS NOT NULL ORDER BY `menus`.`id` LIMIT 1) g14);
UPDATE `menus` SET `name` = 'Attendance', `order` = 3, `updated_at` = NOW() WHERE `id` = (SELECT `gid` FROM (SELECT `parent_id` AS `gid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `url` = 'get.learner.attendance' AND `parent_id` IS NOT NULL ORDER BY `menus`.`id` LIMIT 1) g15);
UPDATE `menus` SET `order` = 4, `updated_at` = NOW() WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `parent_id` IS NULL AND `url` = 'chat.index';
UPDATE `menus` SET `name` = 'Reports', `url` = 'reports.hub', `order` = 5, `updated_at` = NOW() WHERE `id` = (SELECT `gid` FROM (SELECT `id` AS `gid` FROM `menus` WHERE `parent_id` IS NULL AND `deleted_at` IS NULL AND `has_permissions` = 'Manage Report' ORDER BY `menus`.`id` LIMIT 1) gr1);
UPDATE `menus` SET `name` = 'Setup', `url` = 'branch.list', `order` = 6, `has_permissions` = NULL, `updated_at` = NOW() WHERE `id` = (SELECT `gid` FROM (SELECT `parent_id` AS `gid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `url` = 'branch.list' AND `parent_id` IS NOT NULL ORDER BY `menus`.`id` LIMIT 1) g16);
UPDATE `menus` SET `name` = 'Settings', `order` = 8, `updated_at` = NOW() WHERE `id` = (SELECT `gid` FROM (SELECT `parent_id` AS `gid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `url` = 'toggle.feature' AND `parent_id` IS NOT NULL ORDER BY `menus`.`id` LIMIT 1) g17);
UPDATE `menus` SET `name` = 'Account', `url` = 'profile', `order` = 9, `updated_at` = NOW() WHERE `id` = (SELECT `gid` FROM (SELECT `parent_id` AS `gid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `url` = 'profile' AND `parent_id` IS NOT NULL ORDER BY `menus`.`id` LIMIT 1) g18);
UPDATE `menus` SET `status` = 0, `updated_at` = NOW() WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `parent_id` IS NULL AND `name` IN ('Trxn Management', 'Subscription');
-- Reports: sub-links get their new names but are hidden
UPDATE `menus` m JOIN (
              SELECT 'reports.hub' AS `url`, 'Overview' AS `name`, 1 AS `ord`
    UNION ALL SELECT 'payment.collection.report', 'Collections', 2
    UNION ALL SELECT 'monthly.payment.collection.report', 'Cash book', 3
    UNION ALL SELECT 'report.monthly', 'Profit & loss', 4
    UNION ALL SELECT 'partial.payment.collection.report', 'Dues to collect', 5
    UNION ALL SELECT 'upcoming.payment.report', 'Renewals', 6
    UNION ALL SELECT 'learner.report', 'Members', 7
    UNION ALL SELECT 'reports.growth', 'Growth & retention', 8
    UNION ALL SELECT 'reports.occupancy', 'Seat occupancy', 9
    UNION ALL SELECT 'attendance.report', 'Attendance', 10
) v ON v.`url` = m.`url`
SET m.`name` = v.`name`, m.`order` = v.`ord`, m.`status` = 0, m.`updated_at` = NOW()
WHERE m.`parent_id` = (SELECT `gid` FROM (SELECT `id` AS `gid` FROM `menus` WHERE `parent_id` IS NULL AND `deleted_at` IS NULL AND `has_permissions` = 'Manage Report' ORDER BY `menus`.`id` LIMIT 1) gr1);
UPDATE `menus` SET `status` = 0, `updated_at` = NOW() WHERE `parent_id` = (SELECT `gid` FROM (SELECT `id` AS `gid` FROM `menus` WHERE `parent_id` IS NULL AND `deleted_at` IS NULL AND `has_permissions` = 'Manage Report' ORDER BY `menus`.`id` LIMIT 1) gr1);

