WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `url` = 'library.enquiry' AND (`parent_id` IS NULL OR `parent_id` IN (SELECT `tid` FROM (SELECT DISTINCT `id` AS `tid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `parent_id` IS NULL) t20));
UPDATE `menus` SET `parent_id` = (SELECT `gid` FROM (SELECT `parent_id` AS `gid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `url` = 'profile' AND `parent_id` IS NOT NULL ORDER BY `menus`.`id` LIMIT 1) g21), `name` = 'Referral', `order` = 4, `status` = 1, `updated_at` = NOW()
WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `url` = 'referral.dashboard' AND (`parent_id` IS NULL OR `parent_id` IN (SELECT `tid` FROM (SELECT DISTINCT `id` AS `tid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `parent_id` IS NULL) t22));
UPDATE `menus` SET `parent_id` = (SELECT `gid` FROM (SELECT `parent_id` AS `gid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `url` = 'toggle.feature' AND `parent_id` IS NOT NULL ORDER BY `menus`.`id` LIMIT 1) g23), `name` = 'Library Settings', `order` = 1, `status` = 1, `updated_at` = NOW()
WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `url` = 'library.settings' AND `parent_id` IN ((SELECT `gid` FROM (SELECT `parent_id` AS `gid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `url` = 'toggle.feature' AND `parent_id` IS NOT NULL ORDER BY `menus`.`id` LIMIT 1) g24), (SELECT `gid` FROM (SELECT `parent_id` AS `gid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `url` = 'profile' AND `parent_id` IS NOT NULL ORDER BY `menus`.`id` LIMIT 1) g25));

-- every other link: group, name, order (only links that sit under a top-level library menu)
-- learners
