WHERE m.`guard` = 'library' AND m.`deleted_at` IS NULL AND m.`parent_id` IN (SELECT `tid` FROM (SELECT DISTINCT `id` AS `tid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `parent_id` IS NULL) t34) AND (SELECT `gid` FROM (SELECT `parent_id` AS `gid` FROM `menus` WHERE `guard` = 'library' AND `deleted_at` IS NULL AND `url` = 'toggle.feature' AND `parent_id` IS NOT NULL ORDER BY `menus`.`id` LIMIT 1) g33) IS NOT NULL;
