INSERT IGNORE INTO `role_has_permissions` (`permission_id`, `role_id`) SELECT p.`id`, r.`id` FROM `permissions` p JOIN `roles` r ON r.`name` = 'CRM Manager' AND r.`guard_name` = 'web'
WHERE p.`guard_name` = 'web' AND p.`name` IN ('crm-view-dashboard', 'crm-view-leads', 'crm-view-all-leads', 'crm-create-leads', 'crm-edit-leads', 'crm-delete-leads', 'crm-assign-leads', 'crm-import-leads', 'crm-export-leads', 'crm-log-calls', 'crm-send-messages', 'crm-manage-reminders', 'crm-manage-settings');
