INSERT IGNORE INTO `role_has_permissions` (`permission_id`, `role_id`) SELECT p.`id`, r.`id` FROM `permissions` p JOIN `roles` r ON r.`name` = 'Calling Agent' AND r.`guard_name` = 'web'
WHERE p.`guard_name` = 'web' AND p.`name` IN ('crm-view-dashboard', 'crm-view-leads', 'crm-create-leads', 'crm-edit-leads', 'crm-log-calls', 'crm-send-messages', 'crm-manage-reminders');
-- superadmin gets every admin-portal (guard web) permission, crm-* included
INSERT IGNORE INTO `role_has_permissions` (`permission_id`, `role_id`) SELECT p.`id`, r.`id` FROM `permissions` p JOIN `roles` r ON r.`name` = 'superadmin' AND r.`guard_name` = 'web'
WHERE p.`guard_name` = 'web' AND p.`deleted_at` IS NULL;

-- Calling CRM: leads of the old /leads page (lead_contacts) copied in, stage New > Uploaded.
-- Mobile = last 10 digits; a mobile already in crm_leads is skipped.
INSERT INTO `crm_leads` (`contact_name`, `library_name`, `mobile`, `city`, `source`, `stage_id`, `sub_stage_id`, `notes`, `created_at`, `updated_at`)
SELECT lc.`name`, lc.`library_name`, RIGHT(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(lc.`mobile`, ' ', ''), '+', ''), '-', ''), '(', ''), ')', ''), '.', ''), '/', ''), 10), lc.`city`, 'old-leads',
       (SELECT `id` FROM `crm_stages` WHERE `slug` = 'new'), (SELECT `id` FROM `crm_stages` WHERE `slug` = 'new-uploaded'),
       NULLIF(TRIM(CONCAT(IF(lc.`lead_status` IS NULL OR lc.`lead_status` = '', '', CONCAT('Old lead status: ', lc.`lead_status`)), IF(lc.`status` IS NULL OR lc.`status` = '', '', CONCAT(' · call status: ', lc.`status`)))), ''),
       COALESCE(lc.`created_at`, NOW()), NOW()
FROM `lead_contacts` lc
JOIN (SELECT MIN(`id`) AS `id` FROM `lead_contacts` GROUP BY RIGHT(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`mobile`, ' ', ''), '+', ''), '-', ''), '(', ''), ')', ''), '.', ''), '/', ''), 10)) firsts ON firsts.`id` = lc.`id`
WHERE RIGHT(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(lc.`mobile`, ' ', ''), '+', ''), '-', ''), '(', ''), ')', ''), '.', ''), '/', ''), 10) REGEXP '^[0-9]{10}$'
  AND NOT EXISTS (SELECT 1 FROM `crm_leads` x WHERE x.`mobile` = RIGHT(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(lc.`mobile`, ' ', ''), '+', ''), '-', ''), '(', ''), ')', ''), '.', ''), '/', ''), 10));

-- Free 'Pending Payment Reminder' (operation 18) templates: WhatsApp + SMS, only when that channel has none
INSERT INTO `notification_templates` (`operation_id`, `type`, `template_name`, `template_code`, `template_message`, `is_active`, `is_custom`, `is_paid`, `created_at`, `updated_at`)
SELECT 18, 'waba', 'pending-payment', 'pending-payment', 'Hi {{learner_name}},\n\nYour future is built by the effort you put in today. Stay focused, stay consistent, and don’t let small things come between you and your dream. 💙\n\nWe noticed your payment due on {{due_date}} is still pending. Please clear it at the earliest and keep your full focus on achieving your goal.\n\nYour Best Wisher,\n{{library_name}} Library 📚', 1, 0, '0', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `notification_templates` x WHERE x.`operation_id` = 18 AND x.`type` = 'waba');
INSERT INTO `notification_templates` (`operation_id`, `type`, `template_name`, `template_code`, `template_message`, `is_active`, `is_custom`, `is_paid`, `created_at`, `updated_at`)
SELECT 18, 'text', 'pending-payment-sms', 'pending-payment-sms', 'Dear {{learner_name}}, your library fee of Rs.{{pending_amount}} due on {{due_date}} is pending. Please pay at the earliest. - {{library_name}}', 1, 0, '0', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `notification_templates` x WHERE x.`operation_id` = 18 AND x.`type` = 'text');

